import json
from pathlib import Path
from statistics import fmean

METRICS = ("overall", "accuracy", "reasoning", "formatting", "conciseness")

def summarize_reports(reports_dir: Path) -> dict[str, float]:
    """Compute mean component scores across all student-trained JSON reports."""
    paths = sorted(reports_dir.glob("grade_student-trained_*.json"))
    if not paths:
        raise ValueError(f"no trained grade reports found in {reports_dir}")
    buckets: dict[str, list[float]] = {m: [] for m in METRICS}
    for p in paths:
        data = json.loads(p.read_text(encoding="utf-8"))
        summary = data.get("summary", data)
        for m in METRICS:
            if m in summary:
                buckets[m].append(float(summary[m]))
    return {m: round(fmean(vals), 3) for m, vals in buckets.items() if vals}
